def now():
    return np.array(json.loads((ROOT/'last_meta.json').read_text())['proprio']['now'])
def eep():
    n=now(); return np.r_[n[16:23],n[7],n[23:30],n[15]]
def qseed():
    n=now();return np.r_[n[:7],n[8:15]]
def quat(R):
    return Rotation.from_matrix(R).as_quat()[[3,0,1,2]]
def rot(q):
    return Rotation.from_quat(np.asarray(q)[[1,2,3,0]]).as_matrix()
def move(name,right=None,left=None,rg=None,lg=None,steps=1):
    a=eep();b=a.copy()
    if right is not None:b[:7]=right
    if left is not None:b[8:15]=left
    if rg is not None:b[7]=rg
    if lg is not None:b[15]=lg
    rows=[]
    for t in np.linspace(1/steps,1,steps):
        p=a*(1-t)+b*t
        for s in [0,8]:
            rs=Rotation.from_quat(np.array([a[s+3:s+7],b[s+3:s+7]])[:,[1,2,3,0]])
            p[s+3:s+7]=Slerp([0,1],rs)(t).as_quat()[[3,0,1,2]]
        rows.append(p)
    return action(rows,name)
def point(u,v,cam='ego'):
    m=json.loads((ROOT/'last_meta.json').read_text())['cameras'][cam]
    K=np.array(m['intrinsic_cv']);E=np.array(m['extrinsic_cv']);d=np.load(ROOT/(cam+'_depth.npy'))
    c=np.linalg.inv(K)@np.array([u,v,1])*d[v,u]
    return E[:,:3].T@(c-E[:,3])
def summary():
    n=now();print('R',n[16:23].round(4),'L',n[23:30].round(4),'grips',n[[62,63]].round(4))
    print('efforts',n[64:].round(2))
DOWN=quat(np.array([[0,1,0],[1,0,0],[0,0,-1]]))
